    final JLabel draftProfile=new JLabel(),previewProfile=new JLabel(),publishedProfile=new JLabel();
    final JSpinner radius=new JSpinner(new SpinnerNumberModel(12d,8d,18d,.5d)),width=new JSpinner(new SpinnerNumberModel(22d,8d,28d,.5d));
